def bfs_path(I,start,end,wall):
    H=len(I);W=len(I[0]);prev={}
    dq=collections.deque([start]); prev[start]=None
    while dq:
        c=dq.popleft()
        if c==end: break
        i,j=c
        for ni,nj in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)):
            if 0<=ni<H and 0<=nj<W and I[ni][nj]!=wall and (ni,nj) not in prev:
                prev[(ni,nj)]=c; dq.append((ni,nj))
    cur=end; path=[]
    while True:
        i,j=cur; path.append((i,j)); 
        if cur==start: break
        cur=prev[cur]
    return path[::-1]
